    "models.toDownloadPicked": "{size} \u0437\u0430\u0432\u0430\u043D\u0442\u0430\u0436\u0438\u0442\u044C\u0441\u044F, \u043A\u043E\u043B\u0438 \u0432\u0438\u0431\u0435\u0440\u0435\u0442\u0435",
